code='''from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0]); bg=Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col==bg or (r,c) in seen: continue
        q=deque([(r,c)]); seen.add((r,c)); cells=[]
        while q:
          y,x=q.popleft(); cells.append((y,x))
          for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
            yy,xx=y+dy,x+dx
            if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==col:
              seen.add((yy,xx)); q.append((yy,xx))
        comps.append((col,cells))
    # A border-reaching, connected L is the color source.
    marker=None
    for col,cells in comps:
      S=set(cells); rs=[y for y,x in cells]; cs=[x for y,x in cells]
      if len(cells)<4: continue
      for y,x in cells:
        dirs=[]
        for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
          if (y+dy,x+dx) in S: dirs.append((dy,dx))
        if any(a[0]*b[0]+a[1]*b[1]==0 for i,a in enumerate(dirs) for b in dirs[i+1:]):
          # use an L with a long arm and a contact near two adjacent edges
          if (min(rs)==0 or max(rs)==h-1) and (min(cs)==0 or max(cs)==w-1):
            marker=(col,S,(y,x),dirs); break
      if marker: break
    if marker is None: return [row[:] for row in grid]
    mc,S,(ey,ex),dirs=marker
    # The intended region is diagonally opposite the two arms of the L.
    vertical=next((dy for dy,dx in dirs if dx==0),0)
    horizontal=next((dx for dy,dx in dirs if dy==0),0)
    out=[row[:] for row in grid]
    for y in range(h):
      for x in range(w):
        if ((y-ey)*vertical<0 and (x-ex)*horizontal<0 and grid[y][x]!=bg and grid[y][x]!=mc):
          out[y][x]=mc
    return out
'''
